            margin: 0;
            font-size: 22px;
            font-weight: 600;
        }
        .content {
            padding: 24px 20px;
        }
        .content p {
            margin: 0 0 15px 0;
        }
        .summary {
            background: #f8f9fa;
            border-left: 4px solid {% if status == ''Success'' %}#4CAF50{% else %}#E53E3E{% endif %};
            border-radius: 4px;
            padding: 12px 16px;
            white-space: pre-wrap;
            word-break: break-word;
        }
        .meta {
            color: #757575;
            font-size: 13px;
            margin-top: 20px;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h2>Routine "{{ routine.Name }}" {% if status == ''Success'' %}completed{% else %}failed{% endif %}</h2>
        </div>
        <div class="content">
            <p>
