                <strong>{{ status }}</strong>.
            </p>
            {% if resultSummary %}
            <div class="summary">{{ resultSummary }}</div>
            {% endif %}
            {% if run.ErrorMessage %}
            <p><strong>Error:</strong> {{ run.ErrorMessage }}</p>
            {% endif %}
            <p class="meta">
                Started: {{ run.StartedAt }}<br />
                Completed: {{ run.CompletedAt }}
            </p>
        </div>
    </div>
</body>
