  p_LockedByInstance_428ea585 VARCHAR(255);
  p_ExpectedCompletionAt_428ea585 TIMESTAMPTZ;
  p_ConcurrencyMode_428ea585 VARCHAR(20);
  p_RunImmediatelyIfNeverRun_428ea585 BOOLEAN;
  p_MaxRuntimeMinutes_428ea585 INTEGER;
BEGIN
  IF EXISTS (SELECT 1 FROM __mj."ScheduledJob" WHERE "ID" = '07C5F06E-239F-4575-9687-2C1075B153E6') THEN
    RETURN; -- already seeded (sync-pushed or whole-baseline database)
  END IF;
  p_ID_428ea585 := '07C5F06E-239F-4575-9687-2C1075B153E6';
  p_JobTypeID_428ea585 := 'C15849E1-7537-4C03-B5B1-003E7103D789';
  p_Name_428ea585 := 'User Routine Dispatcher';
  p_Description_428ea585 := 'Every-minute sweep that claims and executes due user routines (MJ: User Routines) — the single dispatcher behind the User Routines feature. Claims each due routine by advancing NextRunAt BEFORE running so an overlapping pass can never double-run it; ConcurrencyMode=Skip additionally prevents two dispatcher sweeps from running concurrently across servers. Routine-level failures are isolated and recorded on their MJ: User Routine Runs rows — the sweep itself only fails on infrastructure errors.';
  p_CronExpression_428ea585 := '0 * * * * *';
  p_Timezone_428ea585 := 'UTC';
  p_Status_428ea585 := 'Active';
  p_Configuration_428ea585 := '{
  "MaxConcurrentRoutines": 3
}';
  p_RunCount_428ea585 := 0;
  p_SuccessCount_428ea585 := 0;
  p_FailureCount_428ea585 := 0;
  p_NotifyOnSuccess_428ea585 := FALSE;
  p_NotifyOnFailure_428ea585 := TRUE;
  p_NotifyViaEmail_428ea585 := FALSE;
  p_NotifyViaInApp_428ea585 := TRUE;
  p_ConcurrencyMode_428ea585 := 'Skip';
  p_RunImmediatelyIfNeverRun_428ea585 := FALSE;
  PERFORM __mj."spCreateScheduledJob"(p_ID := p_ID_428ea585, p_JobTypeID := p_JobTypeID_428ea585, p_Name := p_Name_428ea585, p_Description := p_Description_428ea585, p_CronExpression := p_CronExpression_428ea585, p_Timezone := p_Timezone_428ea585, p_StartAt := p_StartAt_428ea585, p_StartAt_Clear := TRUE, p_EndAt := p_EndAt_428ea585, p_EndAt_Clear := TRUE, p_Status := p_Status_428ea585, p_Configuration := p_Configuration_428ea585, p_OwnerUserID := p_OwnerUserID_428ea585, p_OwnerUserID_Clear := TRUE, p_LastRunAt := p_LastRunAt_428ea585, p_LastRunAt_Clear := TRUE, p_NextRunAt := p_NextRunAt_428ea585, p_NextRunAt_Clear := TRUE, p_RunCount := p_RunCount_428ea585, p_SuccessCount := p_SuccessCount_428ea585, p_FailureCount := p_FailureCount_428ea585, p_NotifyOnSuccess := p_NotifyOnSuccess_428ea585, p_NotifyOnFailure := p_NotifyOnFailure_428ea585, p_NotifyUserID := p_NotifyUserID_428ea585, p_NotifyUserID_Clear := TRUE, p_NotifyViaEmail := p_NotifyViaEmail_428ea585, p_NotifyViaInApp := p_NotifyViaInApp_428ea585, p_LockToken := p_LockToken_428ea585, p_LockToken_Clear := TRUE, p_LockedAt := p_LockedAt_428ea585, p_LockedAt_Clear := TRUE, p_LockedByInstance := p_LockedByInstance_428ea585, p_LockedByInstance_Clear := TRUE, p_ExpectedCompletionAt := p_ExpectedCompletionAt_428ea585, p_ExpectedCompletionAt_Clear := TRUE, p_ConcurrencyMode := p_ConcurrencyMode_428ea585, p_RunImmediatelyIfNeverRun := p_RunImmediatelyIfNeverRun_428ea585, p_MaxRuntimeMinutes := p_MaxRuntimeMinutes_428ea585, p_MaxRuntimeMinutes_Clear := TRUE);
END $mj$;

